///////////////////////////////////////////////////////////////////////////////
// class Config_PushServer
///////////////////////////////////////////////////////////////////////////////
Config_PushServer::Config_PushServer()
{
	m_apns_production = 0;
}

Config_PushServer::~Config_PushServer()
{
	// empty
}

int Config_PushServer::parse_bytes(const byte* src, uint32 len)
{
	if (src == NULL) return -1;
	if (len < sizeof(uint32)) return -1;
	uint32 msglen;
	memcpy(&msglen, src, sizeof(uint32));
	if (msglen < sizeof(uint32) || msglen > len) return -1;
	Aone2Decoder decoder(src + sizeof(uint32), msglen - sizeof(uint32));

	// m_listen_aone_rc4
	if (decoder.remain() == 0) return msglen;
	int listen_aone_rc4_ret = m_listen_aone_rc4.parse_bytes(decoder.position(), decoder.remain());
	if (listen_aone_rc4_ret <= 0) return listen_aone_rc4_ret;
	if (!decoder.set_pos(decoder.position() + listen_aone_rc4_ret)) return -1;

	// m_log_info
	if (decoder.remain() == 0) return msglen;
	int log_info_ret = m_log_info.parse_bytes(decoder.position(), decoder.remain());
	if (log_info_ret <= 0) return log_info_ret;
	if (!decoder.set_pos(decoder.position() + log_info_ret)) return -1;

	// m_redis_info
	if (decoder.remain() == 0) return msglen;
	int redis_info_ret = m_redis_info.parse_bytes(decoder.position(), decoder.remain());
	if (redis_info_ret <= 0) return redis_info_ret;
	if (!decoder.set_pos(decoder.position() + redis_info_ret)) return -1;

	// m_apns_production
	if (decoder.remain() == 0) return msglen;
	if (!decoder.get_uint16(m_apns_production)) return -1;

	// m_apns
	if (decoder.remain() == 0) return msglen;
	uint32 apns_count = 0;
	if (!decoder.get_uint32(apns_count)) return -1;
	for(uint32 i = 0; i < apns_count; i++)
	{
		m_apns.push_back(ApnsInfo());
		ApnsInfo& apns_ = m_apns.back();
		int apns_ret = apns_.parse_bytes(decoder.position(), decoder.remain());
		if (apns_ret <= 0) return apns_ret;
		if (!decoder.set_pos(decoder.position() + apns_ret)) return -1;
	}

	return msglen;
}

int Config_PushServer::to_bytes(byte* dst, uint32 maxlen)
{
	if (dst == NULL) return -1;
	if (maxlen < sizeof(uint32)) return -1;
	Aone2Coder coder(dst + sizeof(uint32), maxlen - sizeof(uint32));

	// m_listen_aone_rc4
	int listen_aone_rc4_ret = m_listen_aone_rc4.to_bytes(coder.position(), coder.remain());
	if (listen_aone_rc4_ret <= 0) return listen_aone_rc4_ret;
	coder.set_pos(coder.position() + listen_aone_rc4_ret);

	// m_log_info
	int log_info_ret = m_log_info.to_bytes(coder.position(), coder.remain());
	if (log_info_ret <= 0) return log_info_ret;
	coder.set_pos(coder.position() + log_info_ret);

	// m_redis_info
	int redis_info_ret = m_redis_info.to_bytes(coder.position(), coder.remain());
	if (redis_info_ret <= 0) return redis_info_ret;
	coder.set_pos(coder.position() + redis_info_ret);

	// m_apns_production
	if (!coder.set_uint16(m_apns_production)) return -1;

	// m_apns
	if (!coder.set_uint32(m_apns.size())) return -1;
	for(uint32 i = 0; i < (uint32)m_apns.size(); i++)
	{
		int apns_ret = m_apns[i].to_bytes(coder.position(), coder.remain());
		if (apns_ret <= 0) return apns_ret;
		coder.set_pos(coder.position() + apns_ret);
	}

	uint32 l = (coder.position() - dst);
	memcpy(dst, &l, sizeof(uint32));
	return l;
}

uint32 Config_PushServer::calc_length()
{
	uint32 length = 0;

	// m_listen_aone_rc4
	length += m_listen_aone_rc4.calc_length();

	// m_log_info
	length += m_log_info.calc_length();

	// m_redis_info
	length += m_redis_info.calc_length();

	// m_apns_production
	length += Aone2Coder::size_uint16(m_apns_production);

	// m_apns
	length += sizeof(uint32);
	for(uint32 i = 0; i < m_apns.size(); i++)
	{
		length += m_apns[i].calc_length();
	}

	return length + sizeof(uint32);
}

